for(const locale of Object.keys(PHONE_COPY))PHONE_COPY[locale].declaredRoute=declaredRoutes[locale];
const saveAndSimulate={it:'Salva la scheda e simula',en:'Save the card and simulate',fr:'Enregistrer la fiche et simuler',es:'Guardar la ficha y simular',pt:'Guardar a ficha e simular'};
for(const locale of Object.keys(PHONE_COPY))PHONE_COPY[locale].saveAndSimulate=saveAndSimulate[locale];
for(const [locale,localProofReview]of Object.entries({
  it:'Per attivare il profilo salviamo prima la mappa. Le prove dichiarate solo in questa sessione tornano da riesaminare: dopo la conferma del salvataggio potrai dichiararle di nuovo.',
  en:'To enable the profile, we save the map first. Tests declared only in this session need review: after the save is confirmed, you can declare them again.',
  fr:'Pour activer le profil, nous enregistrons d’abord la carte. Les essais déclarés dans cette session sont à réexaminer : après confirmation de l’enregistrement, vous pourrez les déclarer à nouveau.',
  es:'Para activar el perfil, primero guardamos el mapa. Las pruebas declaradas solo en esta sesión requieren revisión: tras confirmar el guardado, podrás declararlas de nuevo.',
  pt:'Para ativar o perfil, guardamos primeiro o mapa. Os testes declarados apenas nesta sessão precisam de revisão: após a confirmação da gravação, poderá declará-los de novo.'
}))Object.assign(PHONE_COPY[locale],{localProofReview});
for(const value of Object.values(PHONE_COPY)){for(const entry of Object.values(value))if(entry&&typeof entry==='object')Object.freeze(entry);Object.freeze(value);}
export function phoneCopy(locale){if(!Object.hasOwn(PHONE_COPY,locale))throw Error('UNSUPPORTED_LOCALE');return PHONE_COPY[locale];}

